const tr=k=>T[state.lang][k]||k;
function applyI18n(){document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=tr(e.dataset.i18n));document.querySelectorAll('[data-i18n-placeholder]').forEach(e=>e.placeholder=tr(e.dataset.i18nPlaceholder));document.querySelectorAll('[data-i18n-title]').forEach(e=>e.title=tr(e.dataset.i18nTitle));renderThreads();renderApprovals();renderModelControls();renderMethods();renderOfficialEvents();if(state.capabilities)renderCapabilities(state.capabilities);if(state.selectedMethod){const info=readableMethodInfo(state.selectedMethod);$('methodHumanTitle').textContent=info.title;$('methodGroup').textContent=`${tr('methodGroup')} · ${info.group} · ${methodKindLabel($('methodKind').value)}`}$('statusLine')&&updateStatus()}
const DEFAULT_API_TIMEOUT_MS=45_000;
async function api(path,options={}){
  const {signal:callerSignal,timeoutMs=DEFAULT_API_TIMEOUT_MS,...fetchOptions}=options;
  const controller=new AbortController();let timedOut=false;
  const forwardAbort=()=>controller.abort(callerSignal?.reason);
  if(callerSignal){if(callerSignal.aborted)forwardAbort();else callerSignal.addEventListener('abort',forwardAbort,{once:true})}
  const timeout=Number(timeoutMs),limit=Number.isFinite(timeout)?Math.max(0,timeout):DEFAULT_API_TIMEOUT_MS;
  const timer=limit?window.setTimeout(()=>{timedOut=true;controller.abort()},limit):null;
  try{
    const r=await fetch(path,{credentials:'same-origin',...fetchOptions,signal:controller.signal,headers:{...(fetchOptions.body?{'Content-Type':'application/json'}:{}),...(fetchOptions.headers||{})}}),body=await r.json().catch(()=>({}));
    if(!r.ok){const e=new Error(body.message||body.error||`HTTP ${r.status}`);e.status=r.status;e.body=body;throw e}return body;
  }catch(error){
    if(timedOut){const e=new Error(`Gateway request timed out: ${path}`);e.code='CWEB_HTTP_TIMEOUT';e.status=504;e.cause=error;throw e}
    throw error;
  }finally{if(timer)window.clearTimeout(timer);callerSignal?.removeEventListener('abort',forwardAbort)}
}
async function rpc(method,params={},options={}){return(await api('/api/rpc',{method:'POST',body:JSON.stringify({method,params}),...options})).result}
const respond=(id,result)=>api('/api/respond',{method:'POST',body:JSON.stringify({id,result})});
const respondError=(id,error)=>api('/api/respond',{method:'POST',body:JSON.stringify({id,error})});
const hasRequest=m=>Boolean(state.methods?.requests?.some(x=>x.method===m));
function toast(text,kind=''){const e=document.createElement('div');e.className=`toast ${kind}`;e.textContent=text;$('toastRegion').append(e);setTimeout(()=>e.remove(),4500)}
function shortDate(v){if(!v)return'';const ms=v>1e10?v:v*1000;try{return new Intl.DateTimeFormat(state.lang==='zh'?'zh-CN':'en',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(ms))}catch{return''}}
function threadTitle(t){return t?.name||t?.title||t?.preview||t?.id||'Thread'}
function threadStatus(t){return String(t?.status?.type||t?.status||'').toLowerCase()}
function isActiveOfficialStatus(value){return isOfficialActiveStatus(value)}
function normalizeThreads(r){return r?.data||r?.threads||r?.items||(Array.isArray(r)?r:[])}
state.threadListInFlight=state.threadListInFlight||null;
state.threadListRefreshQueued=Boolean(state.threadListRefreshQueued);
async function refreshThreads(){
  state.threadListSerial=(state.threadListSerial||0)+1;
  if(state.threadListInFlight){state.threadListRefreshQueued=true;return state.threadListInFlight}
  const task=(async()=>{
    let result=false;
    do{
      state.threadListRefreshQueued=false;
      const serial=state.threadListSerial,view=Boolean(state.archivedView);
      try{
        const r=await rpc('thread/list',{limit:100,archived:view,sortKey:'updated_at',sortDirection:'desc'});
        if(serial===state.threadListSerial&&view===Boolean(state.archivedView)){state.threads=normalizeThreads(r);state.threadsLoaded=true;renderThreads();result=true}
      }catch(error){if(serial===state.threadListSerial)console.warn(error)}
    }while(state.threadListRefreshQueued);
    return result;
  })();
  state.threadListInFlight=task;
  try{return await task}
  finally{if(state.threadListInFlight===task)state.threadListInFlight=null}
}
