const MAX_IMAGE_INPUT_BYTES=8*1024*1024,MAX_IMAGE_DATA_CHARS=1100000,MAX_ATTACHMENTS=3,MAX_ATTACHMENT_TOTAL_CHARS=1600000;
function imageFileData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error(tr('imageReadFailed')));reader.onload=()=>{const original=String(reader.result||''),image=new Image();image.onerror=()=>reject(new Error(tr('imageReadFailed')));image.onload=()=>{try{const maxSide=1600,scale=Math.min(1,maxSide/Math.max(image.naturalWidth||image.width,image.naturalHeight||image.height));let data=original;if(scale<1||data.length>MAX_IMAGE_DATA_CHARS){const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round((image.naturalWidth||image.width)*scale));canvas.height=Math.max(1,Math.round((image.naturalHeight||image.height)*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const format=file.type==='image/png'&&data.length<=MAX_IMAGE_DATA_CHARS?'image/png':'image/jpeg';data=canvas.toDataURL(format,0.82);if(data.length>MAX_IMAGE_DATA_CHARS&&format!=='image/jpeg')data=canvas.toDataURL('image/jpeg',0.82)}if(data.length>MAX_IMAGE_DATA_CHARS)throw new Error(tr('imageTooLarge'));resolve({dataUrl:data,width:image.naturalWidth||image.width,height:image.naturalHeight||image.height})}catch(error){reject(error)}};image.src=original};reader.readAsDataURL(file)})}
