function renderAttachments(){const tray=$('attachmentTray');if(!tray)return;tray.classList.toggle('hidden',!state.attachments.length);tray.replaceChildren(...state.attachments.map(item=>{const chip=el('div','attachment-chip');const image=document.createElement('img');image.src=item.dataUrl;image.alt=item.name;const copy=el('span','attachment-copy');copy.append(el('strong','',item.name),el('small','',attachmentSize(item.dataUrl.length)));const remove=el('button','attachment-remove','×');remove.type='button';remove.setAttribute('aria-label',`${tr('removeAttachment')}: ${item.name}`);remove.title=tr('removeAttachment');remove.onclick=()=>{state.attachments=state.attachments.filter(x=>x.id!==item.id);renderAttachments()};chip.append(image,copy,remove);return chip}))}
async function handleAttachmentFiles(files){const selected=[...files].slice(0,MAX_ATTACHMENTS-state.attachments.length);if(!selected.length)return;for(const file of selected){if(!/^image\/(?:png|jpe?g|webp|gif|bmp)$/i.test(file.type)){toast(tr('imageUnsupported'),'error');continue}if(file.size>MAX_IMAGE_INPUT_BYTES){toast(tr('imageTooLarge'),'error');continue}try{const prepared=await imageFileData(file);const total=state.attachments.reduce((sum,item)=>sum+item.dataUrl.length,0)+prepared.dataUrl.length;if(total>MAX_ATTACHMENT_TOTAL_CHARS)throw new Error(tr('imageTooLarge'));state.attachments.push({id:'attachment-'+Date.now()+'-'+Math.random().toString(36).slice(2),name:file.name||tr('pastedImage'),dataUrl:prepared.dataUrl,width:prepared.width,height:prepared.height});renderAttachments()}catch(error){toast(error.message||tr('imageReadFailed'),'error')}}$('attachmentInput').value=''}
