async function steerPrompt(text,attachments){if(!state.currentThread?.id||!state.activeTurnId)return;if(!hasRequest('turn/steer')){toast(tr('noSteerSupport'),'warning');return}if(state.steeringBusy)return;const threadId=state.currentThread.id,expectedTurnId=state.activeTurnId,draft={text,attachments:attachments.slice()};state.steeringBusy=true;state.queuedDirections+=1;$('send').disabled=true;updateStatus();let optimistic=null;try{await ensureThreadLoaded(threadId);optimistic=optimisticUser(text,attachments,'steer');const clientUserMessageId=makeClientUserMessageId(),request=rpc('turn/steer',{threadId,expectedTurnId,input:buildTurnInput(text,attachments),clientUserMessageId});clearComposer();await request;toast(tr('queuedDirection'))}catch(e){optimistic?.remove();if(isUncertainSendError(e))toast(tr('sendMayHaveSucceeded'),'warning');else{restoreComposerFromAttempt(draft);toast(`${tr('sendFailed')}: ${e.message}`,'error')}}finally{state.queuedDirections=Math.max(0,state.queuedDirections-1);state.steeringBusy=false;$('send').disabled=false;updateStatus()}}
