/* A config read every five seconds competes with live turn traffic and is not
 * needed while the official runtime is executing. Keep idle polling sparse;
 * focus/visibility events still request an immediate official config read. */
startConfigSync=()=>{
  if(state.configSyncTimer)clearInterval(state.configSyncTimer);
  const sync=()=>{if(document.visibilityState!=='hidden'&&!state.configSyncBusy&&!state.activeTurnId&&!state.officialThreadActive&&Date.now()-state.controlChangeAt>1200)void loadCodexConfig(true)};
  state.configSyncTimer=window.setInterval(sync,30_000);
  window.addEventListener('focus',sync);
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')sync()});
};

/* Initial history must not wait for the optional model catalogue. The pinned
 * official runtime can take several seconds to answer model/list, while the
 * selected thread and its SSE stream are ready much sooner. Keep the model
 * request in the background during boot and suppress duplicate boot resyncs
 * until the first authoritative restore has completed. */
const loadModelsBeforeInitialRestore=loadModels;
loadModels=async()=>{if(state.initializing){void loadModelsBeforeInitialRestore();return}return loadModelsBeforeInitialRestore()};
const resyncAuthoritativeStateBeforeInitialRestore=resyncAuthoritativeState;
resyncAuthoritativeState=async()=>{if(state.initializing)return null;return resyncAuthoritativeStateBeforeInitialRestore()};
const afterLoginBeforeInitialRestore=afterLogin;
afterLogin=async()=>{state.initializing=true;try{return await afterLoginBeforeInitialRestore()}finally{state.initializing=false}};
const applyI18nBeforeInitialTitleRestore=applyI18n;
applyI18n=()=>{const result=applyI18nBeforeInitialTitleRestore();if(state.currentThread)$('threadTitle').textContent=threadTitle(state.currentThread);return result};

/* A gateway restart can drop the terminal notification while the official
 * runtime continues the Turn. Kick the bounded official Turn reconciliation
 * after the new SSE connection has completed its authoritative restore, and
 * also when the official thread announces idle while the local delivery
 * marker still describes an active Web Turn. */
const connectEventsBeforeTurnReconciliationKick=connectEvents;
connectEvents=()=>{
  const result=connectEventsBeforeTurnReconciliationKick(),es=state.eventSource;
  if(!es||es.__cwebTurnReconciliationKick)return result;
  const previous=es.onmessage;
  es.onmessage=async event=>{
    let message=null;try{message=JSON.parse(event.data)}catch{}
    const value=await previous?.call(es,event);
    if(message?.type==='connected')scheduleTurnReconciliation(0);
    return value;
  };
  es.__cwebTurnReconciliationKick=true;
  return result;
};
const appendLiveBeforeTurnReconciliationKick=appendLive;
appendLive=message=>{
  const result=appendLiveBeforeTurnReconciliationKick(message),method=String(message?.method||''),params=message?.params||{},status=params.status||params.state||params.thread?.status,threadId=params.threadId||params.thread?.id||state.currentThread?.id;
  if(method==='thread/status/changed'&&status&&!isActiveOfficialStatus(status)){scheduleTurnReconciliation(0);queueTerminalThreadRefresh(threadId,{allowActive:true});}
  return result;
};
const appendLiveLegacyBeforeTurnReconciliationKick=appendLiveLegacy;
appendLiveLegacy=message=>{
  const result=appendLiveLegacyBeforeTurnReconciliationKick(message),method=String(message?.method||''),params=message?.params||{},status=params.status||params.state||params.thread?.status,threadId=params.threadId||params.thread?.id||state.currentThread?.id;
  if(method==='thread/status/changed'&&status&&!isActiveOfficialStatus(status)){scheduleTurnReconciliation(0);queueTerminalThreadRefresh(threadId,{allowActive:true});}
  return result;
};
